Suite/Test/Step Name:
CLICK_SAVE_JS = "
	var modal = document.querySelector('#reset-password');
	if (!modal) { var p = document.querySelector('input[name="pass1"]'); modal = p ? p.closest('.modal, [role="dialog"], form, div') : null; }
	if (!modal) return 'NO_MODAL';
	var btns = modal.querySelectorAll('button');
	for (var i = 0; i < btns.length; i++) {
		var b = btns[i]; if (b.offsetParent === null) continue;
		var t = (b.textContent || '').trim().toLowerCase();
		if (t === 'save' || t === '저장') {
			var dis = b.disabled || b.hasAttribute('disabled') || ((b.className || '').toLowerCase().indexOf('disabled') !== -1);
			if (dis) return 'DISABLED';
			b.click();
			return 'CLICKED';
		}
	}
	return 'NO_SAVE';
"

FIND_SETUP_JS = "
	var els = document.querySelectorAll('a, button');
	// 1순위: add-link/blue-text 클래스 + 'setup'/'reset' 텍스트 (2SV 컨트롤 형태)
	for (var i = 0; i < els.length; i++) {
		var c = els[i]; if (c.offsetParent === null) continue;
		var t = (c.textContent || '').trim().toLowerCase();
		var cls = ((c.className || '') + '').toLowerCase();
		if ((t === 'setup' || t === 'reset' || t === 'reset authenticator' || t === 're-setup' || t.indexOf('reset') !== -1) && (cls.indexOf('add-link') !== -1 || cls.indexOf('blue-text') !== -1)) { c.click(); return 'CLICKED:' + t; }
	}
	// 2순위: 짧은 'setup'/'reset' 링크/버튼
	for (var i = 0; i < els.length; i++) {
		var c = els[i]; if (c.offsetParent === null) continue;
		var t = (c.textContent || '').trim().toLowerCase();
		if (t === 'setup' || t === 'reset') { c.click(); return 'CLICKED2:' + t; }
	}
	return 'NOT_FOUND';
"

AUTH_UI_JS = "
	var modalVisible = false;
	var modals = document.querySelectorAll('.modal.in, .modal.show, [role="dialog"]');
	for (var i = 0; i < modals.length; i++) { if (modals[i].offsetParent !== null) { modalVisible = true; break; } }
	var body = (document.body.innerText || '').toLowerCase();
	var hasAuthUi = body.indexOf('qr') !== -1 || body.indexOf('scan') !== -1 || body.indexOf('secret') !== -1 || body.indexOf('verification code') !== -1 || body.indexOf('authenticator') !== -1;
	var hasAuthSection = body.indexOf('authenticator') !== -1 || body.indexOf('two-step') !== -1 || body.indexOf('2-step') !== -1 || body.indexOf('2sv') !== -1;
	return JSON.stringify({ modalVisible: modalVisible, hasAuthUi: hasAuthUi, hasAuthSection: hasAuthSection });
"
